{"code":"        # BUG_63: off-by-one — should be >= so queue never exceeds max_size
        if len(self.queue) >= self.max_size:
            return False

        self.queue.append(message)
        utilization = self.utilization_pct
        if utilization >= 80.0:
            print(
                f"Dead-letter queue utilization warning: {utilization:.1f}% of "
                f"max capacity ({self.max_size})"
            )
        return True","comments":"Prevent enqueue from exceeding max_size and print an operational warning once utilization hits 80%."}
